validate_set_pipe_tier :: proc(t: ^Topology, c: Cmd_Set_Pipe_Tier, cat: ^Catalogs) -> Edit_Error {
	ps, ok := pipe_slot(t, c.pipe)
	if !ok {
		return .Missing_Pipe
	}
	if u32(c.tier) >= u32(len(cat.pipe_tiers)) {
		return .Unknown_Tier
	}
	if c.tier <= t.pipe_tier[ps] {
		return .Not_An_Upgrade
	}
	return .None
}
